package br.com.cineo;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import org.json.*;import java.net.*;import java.io.*;
/** Battery-aware polling; no claim of instant push delivery. */
public class NoticeJob extends JobService {
 volatile boolean stopped=false;
 static void schedule(Context c){android.content.SharedPreferences p=c.getSharedPreferences("cineo_v2",0);JobScheduler scheduler=(JobScheduler)c.getSystemService(JOB_SCHEDULER_SERVICE);if(!p.getBoolean("phone_notices",false)){scheduler.cancel(701);return;}if(!p.contains("notice_since"))p.edit().putString("notice_since",java.time.Instant.now().toString()).apply();scheduler.schedule(new JobInfo.Builder(701,new ComponentName(c,NoticeJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000).setPersisted(true).build());}
 JSONObject api(String method,String path,JSONObject body,String token,String viewer)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(MainActivity.BASE+path).openConnection();try{c.setRequestMethod(method);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("apikey",MainActivity.KEY);if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);if(!viewer.isEmpty())c.setRequestProperty("X-Cineo-Viewer",viewer);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}if(c.getResponseCode()!=200)throw new IOException("Avisos indisponíveis");try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 @Override public boolean onStartJob(JobParameters job){stopped=false;new Thread(()->{try{SharedPreferences p=getSharedPreferences("cineo_v2",0);int hour=java.time.LocalTime.now().getHour(),start=p.getInt("notice_start",8),end=p.getInt("notice_end",22);boolean inHours=start==end||(start<end?hour>=start&&hour<end:hour>=start||hour<end);if(!p.getBoolean("phone_notices",false)||!inHours)return;JSONObject secret=SessionStore.read(this);String uid=secret.optString("uid");if(uid.isEmpty()||!uid.equals(p.getString("notice_account","")))return;JSONObject refresh=api("POST","/refresh",new JSONObject().put("refresh_token",secret.getString("refresh_token")),"","");secret.put("refresh_token",refresh.getString("refresh_token"));SessionStore.write(this,secret);String token=refresh.getString("token"),viewer=p.getString(uid+":viewer_token","");String since=p.getString("notice_since",java.time.Instant.now().toString());int count=0;
 if(p.getBoolean("notice_episodes",true)){JSONArray rows=api("GET","/v4/notifications",null,token,viewer).getJSONArray("items");for(int i=0;i<rows.length();i++)if(rows.optJSONObject(i).optString("created_at").compareTo(since)>0)count++;}
 if(p.getBoolean("notice_corrections",true)){JSONArray rows=api("GET","/v7/bulletins",null,token,viewer).getJSONArray("items");for(int i=0;i<rows.length();i++)if(rows.optJSONObject(i).optString("created_at").compareTo(since)>0)count++;}
 if(stopped)return;if(count>0){NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("cineo_episodes","Novidades do Cineo",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(this,MainActivity.class);PendingIntent intent=PendingIntent.getActivity(this,701,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT<33||checkSelfPermission("android.permission.POST_NOTIFICATIONS")==android.content.pm.PackageManager.PERMISSION_GRANTED){manager.notify(701,new Notification.Builder(this,"cineo_episodes").setSmallIcon(R.mipmap.ic_launcher).setContentTitle("Novidades nas suas histórias").setContentText(count+" novo(s) aviso(s) no Cineo.").setContentIntent(intent).setAutoCancel(true).build());p.edit().putString("notice_since",java.time.Instant.now().toString()).apply();}}}catch(Exception ignored){/* Next permitted job retries; no tokens or private responses are logged. */}finally{jobFinished(job,false);}},"cineo-notices").start();return true;}
 @Override public boolean onStopJob(JobParameters job){stopped=true;return true;}
}
